#!/usr/bin/env python3
"""Formats an oracle-checked v7 vector dump as the Rust module `vectors.rs`.

Usage: format_vectors.py <vector dump> <output vectors.rs>

Every vector is checked with the oracle before it is written. Standard library only.
"""

import importlib.util
import sys
from pathlib import Path

NAMES = {0: "transparent", 1: "coinbase", 2: "Sapling", 3: "Orchard", 4: "Ironwood", 5: "fee",
         6: "NSM"}

HEADER = '''//! Known-answer vectors for typed v7 transactions.
//!
//! Generated by `dump_vectors_for_oracle` and checked against an independent
//! implementation of the ZIP 248 digests written in Python from the ZIP text alone
//! (`scripts/zip248/oracle.py`); `scripts/zip248/README.md` describes how to regenerate
//! them. Each transaction is shaped like one consensus could accept: its value pool
//! deltas balance, a coinbase transaction spends nothing, and none has an NSM delta,
//! which this implementation assumes NU7.1 does not activate. Their signatures and proofs
//! do not verify.

pub(crate) struct TestVector {
    /// A human-readable summary of the bundles present.
    pub(crate) bundles: &'static str,
    pub(crate) tx: &'static str,
    /// The values of the outputs that the transparent inputs spend.
    pub(crate) amounts: &'static [u64],
    /// The script public keys of the outputs that the transparent inputs spend.
    pub(crate) script_pubkeys: &'static [&'static str],
    pub(crate) txid: &'static str,
    pub(crate) auth_digest: &'static str,
    /// Each signature, labelled `t <input>` or `s <bundle type> <spend or action | b>`,
    /// with its variant 0 signature digest.
    pub(crate) sighashes: &'static [(&'static str, &'static str)],
}

pub(crate) const TEST_VECTORS: &[TestVector] = &['''


def load_oracle():
    path = Path(__file__).with_name("oracle.py")
    spec = importlib.util.spec_from_file_location("zip248_oracle", path)
    oracle = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(oracle)
    return oracle


def format_vector(oracle, vector):
    _, _, deltas, effects, auths = oracle.parse(bytes.fromhex(vector["tx"]))

    def join(entries):
        return ", ".join(NAMES[t] for t, _, _ in entries) or "none"

    tx = vector["tx"]
    out = ["    TestVector {"]
    out.append(f'        bundles: "deltas: {join(deltas)}; effects: {join(effects)}; '
               f'auth: {join(auths)}",')
    if len(tx) <= 88:
        out.append(f'        tx: "{tx}",')
    else:
        out.append("        tx: concat!(")
        out.extend(f'            "{tx[i:i + 88]}",' for i in range(0, len(tx), 88))
        out.append("        ),")
    out.append("        amounts: &[" + ", ".join(str(a) for a in vector["amounts"]) + "],")
    out.append("        script_pubkeys: &["
               + ", ".join(f'"{s.hex()}"' for s in vector["scripts"]) + "],")
    out.append(f'        txid: "{vector["txid"]}",')
    out.append(f'        auth_digest: "{vector["auth"]}",')
    out.append("        sighashes: &[")
    out.extend(f'            ("{label}", "{digest}"),' for label, digest in vector["sigs"])
    out.append("        ],")
    out.append("    },")
    return out


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    if len(argv) != 2:
        sys.exit("usage: format_vectors.py <vector dump> <output vectors.rs>")
    dump_path, out_path = argv
    oracle = load_oracle()
    vectors = oracle.read_vectors(dump_path)
    out = [HEADER]
    for vector in vectors:
        oracle.check_vector(vector)
        out.extend(format_vector(oracle, vector))
    out.append("];\n")
    Path(out_path).write_text("\n".join(out))


if __name__ == "__main__":
    main()
